/* StreamWave Design System */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  /* Color Palette — OKLCH */
  --bg-primary: oklch(0% 0 0);
  --bg-surface: oklch(14.5% 0.01 0);
  --bg-elevated: oklch(20% 0.01 0);
  --bg-card: oklch(17% 0.01 0);
  --accent: oklch(55% 0.26 25);
  --accent-hover: oklch(58% 0.28 25);
  --accent-dark: oklch(35% 0.20 25);
  --text-primary: oklch(100% 0 0);
  --text-secondary: oklch(75% 0 0);
  --text-muted: oklch(55% 0 0);
  --border: oklch(30% 0 0);
  --border-light: oklch(40% 0 0);

  /* Typography */
  --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --fs-hero: clamp(2rem, 5vw, 3.5rem);
  --fs-h2: clamp(1.5rem, 3.5vw, 2.5rem);
  --fs-h3: clamp(1.125rem, 2vw, 1.5rem);
  --fs-body: clamp(0.875rem, 1.5vw, 1.125rem);
  --fs-small: 0.875rem;
  --fs-xs: 0.75rem;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* Reset */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-main);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

input, select {
  font-family: inherit;
  font-size: inherit;
}

/* ===== HEADER ===== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-sm) var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(to bottom, oklch(0% 0.02 0 / 0.8), transparent);
  transition: background var(--transition-base);
}

.site-header.scrolled {
  background: oklch(0% 0.02 0 / 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.header-left {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.logo {
  font-size: 1.75rem;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--accent);
  text-transform: uppercase;
}

.header-right {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.lang-select {
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 0.4rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  cursor: pointer;
}

.btn-signin {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--fs-small);
  transition: background var(--transition-fast);
  display: inline-block;
}

.btn-signin:hover {
  background: var(--accent-hover);
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: -20px;
  background:
    /* Mosaic of tilted poster-like shapes */
    linear-gradient(135deg, oklch(55% 0.26 25 / 0.15) 0%, transparent 30%),
    linear-gradient(225deg, oklch(50% 0.20 280 / 0.12) 0%, transparent 25%),
    linear-gradient(315deg, oklch(45% 0.18 150 / 0.10) 0%, transparent 28%),
    linear-gradient(45deg, oklch(60% 0.22 50 / 0.12) 0%, transparent 32%),
    linear-gradient(160deg, oklch(55% 0.26 25 / 0.10) 10%, transparent 40%),
    linear-gradient(200deg, oklch(40% 0.15 200 / 0.08) 5%, transparent 35%),
    linear-gradient(340deg, oklch(50% 0.20 300 / 0.10) 8%, transparent 30%),
    linear-gradient(110deg, oklch(45% 0.18 80 / 0.08) 12%, transparent 38%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center top, oklch(0% 0 0 / 0.3), oklch(0% 0 0 / 0.85) 60%),
    radial-gradient(ellipse at center bottom, oklch(0% 0 0 / 0.95), oklch(0% 0 0 / 0.5) 70%);
  z-index: 1;
}

.hero-posters {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  opacity: 0.25;
}

.poster-shape {
  width: 120px;
  height: 170px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  transform: rotate(var(--rot, 0deg)) translateY(var(--ty, 0px));
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: var(--space-xl) var(--space-lg);
}

.hero-title {
  font-size: var(--fs-hero);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.hero-subtitle {
  font-size: var(--fs-h3);
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.hero-prompt {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.email-form {
  display: flex;
  gap: var(--space-xs);
  max-width: 520px;
  margin: 0 auto;
}

.email-form input[type="email"] {
  flex: 1;
  padding: 0.875rem 1rem;
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.email-form input[type="email"]::placeholder {
  color: var(--text-muted);
}

.email-form input[type="email"]:focus {
  border-color: var(--text-secondary);
}

.btn-cta {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  white-space: nowrap;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.btn-cta:hover {
  background: var(--accent-hover);
}

.btn-cta .arrow {
  font-size: 1.25em;
  line-height: 1;
}

.hero-divider {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: var(--bg-surface);
  z-index: 3;
}

/* ===== TRENDING ===== */
.trending {
  background: var(--bg-surface);
  padding: var(--space-xl) var(--space-lg);
}

.section-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-lg);
  letter-spacing: -0.01em;
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--space-sm) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.trending-card {
  position: relative;
  flex: 0 0 200px;
  height: 280px;
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.trending-card:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 30px oklch(0% 0 0 / 0.5);
}

.trending-card .poster-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.trending-card .rank {
  position: absolute;
  bottom: -10px;
  left: -5px;
  z-index: 1;
  font-size: 8rem;
  font-weight: 900;
  line-height: 1;
  color: oklch(100% 0 0 / 0.15);
  -webkit-text-stroke: 2px oklch(100% 0 0 / 0.25);
  letter-spacing: -0.04em;
  pointer-events: none;
}

.trending-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-sm);
  background: linear-gradient(to top, oklch(0% 0 0 / 0.9), transparent);
  z-index: 2;
}

.trending-card .card-title {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.2;
}

.trending-card .card-rank-label {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-top: 2px;
}

.carousel-arrow {
  position: absolute;
  right: -8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: oklch(20% 0 0 / 0.9);
  border: 1px solid var(--border);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.carousel-arrow:hover {
  background: oklch(30% 0 0);
  transform: translateY(-50%) scale(1.1);
}

.carousel-arrow:active {
  transform: translateY(-50%) scale(0.95);
}

/* ===== FEATURES ===== */
.features {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-sm);
}

.feature-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 220px;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition-base);
}

.feature-card:hover {
  transform: translateY(-4px);
}

.feature-card .feature-text h3 {
  font-size: var(--fs-h3);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--space-xs);
}

.feature-card .feature-text p {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.5;
}

.feature-card .feature-icon {
  align-self: flex-end;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: var(--space-sm);
}

.feature-card .feature-icon svg {
  width: 40px;
  height: 40px;
  stroke: var(--text-primary);
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ===== FAQ ===== */
.faq {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  margin-bottom: var(--space-xs);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  font-size: var(--fs-body);
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background var(--transition-fast);
  border-radius: var(--radius-sm);
}

.faq-question:hover {
  background: oklch(22% 0.01 0);
}

.faq-question[aria-expanded="true"] {
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.faq-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-question[aria-expanded="true"] .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
  background: var(--bg-card);
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
}

.faq-answer.open {
  max-height: 400px;
}

.faq-answer-inner {
  padding: var(--space-sm) var(--space-md) var(--space-md);
  font-size: var(--fs-body);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== CTA SECTION ===== */
.cta-section {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.cta-section .cta-prompt {
  font-size: var(--fs-h3);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--bg-primary);
  padding: var(--space-xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--border);
}

.footer-contact {
  font-size: var(--fs-small);
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.footer-contact a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-contact a:hover {
  color: var(--text-secondary);
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.footer-links a {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  text-decoration: underline;
  padding: 0.25rem 0;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--text-secondary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.footer-bottom .lang-select {
  margin-bottom: var(--space-sm);
}

.footer-legal {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  max-width: 400px;
  line-height: 1.5;
}

.footer-legal a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-legal a:hover {
  color: var(--text-secondary);
}

/* ===== LOGIN PAGE ===== */
.login-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.login-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-xl) var(--space-lg);
}

.login-card {
  width: 100%;
  max-width: 420px;
  padding: var(--space-lg);
}

.login-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-xs);
}

.login-subtext {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.login-subtext a {
  color: var(--text-secondary);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.login-subtext a:hover {
  color: var(--text-primary);
}

.form-group {
  margin-bottom: var(--space-sm);
  position: relative;
}

.form-group label {
  display: block;
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-bottom: 4px;
  font-weight: 500;
}

.form-group input {
  width: 100%;
  padding: 0.875rem 1rem;
  background: oklch(22% 0.01 0);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.form-group input::placeholder {
  color: var(--text-muted);
}

.form-group input:focus {
  border-color: var(--text-secondary);
}

.btn-login {
  width: 100%;
  padding: 0.875rem;
  background: var(--accent);
  color: var(--text-primary);
  border: none;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  margin-top: var(--space-sm);
  transition: background var(--transition-fast);
}

.btn-login:hover {
  background: var(--accent-hover);
}

.help-toggle {
  margin-top: var(--space-md);
  text-align: center;
}

.help-toggle button {
  color: var(--text-muted);
  font-size: var(--fs-small);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.help-toggle button:hover {
  color: var(--text-secondary);
}

.help-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
  margin-top: var(--space-xs);
}

.help-content.open {
  max-height: 300px;
}

.help-content-inner {
  padding: var(--space-sm);
  background: var(--bg-card);
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.6;
}

.help-content-inner a {
  color: var(--text-secondary);
  text-decoration: underline;
}

.help-content-inner a:hover {
  color: var(--text-primary);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .trending-card {
    flex: 0 0 170px;
    height: 240px;
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--space-sm) var(--space-md);
  }
  .hero-content {
    padding: var(--space-lg) var(--space-md);
  }
  .email-form {
    flex-direction: column;
  }
  .btn-cta {
    justify-content: center;
  }
  .features-grid {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }
  .feature-card {
    min-height: auto;
    padding: var(--space-md);
  }
  .trending-card {
    flex: 0 0 150px;
    height: 210px;
  }
  .trending-card .rank {
    font-size: 6rem;
  }
  .footer-links {
    grid-template-columns: repeat(2, 1fr);
  }
  .cta-section,
  .trending,
  .features,
  .faq {
    padding: var(--space-xl) var(--space-md);
  }
}

@media (max-width: 480px) {
  .logo {
    font-size: 1.35rem;
  }
  .trending-card {
    flex: 0 0 130px;
    height: 185px;
  }
  .trending-card .rank {
    font-size: 5rem;
  }
  .trending-card .card-title {
    font-size: 0.8rem;
  }
  .hero-title {
    font-size: clamp(1.75rem, 7vw, 2.5rem);
  }
  .carousel-arrow {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }
}

/* StreamWave Design System */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  /* Color Palette — OKLCH */
  --bg-primary: oklch(0% 0 0);
  --bg-surface: oklch(14.5% 0.01 0);
  --bg-elevated: oklch(20% 0.01 0);
  --bg-card: oklch(17% 0.01 0);
  --accent: oklch(55% 0.26 25);
  --accent-hover: oklch(58% 0.28 25);
  --accent-dark: oklch(35% 0.20 25);
  --text-primary: oklch(100% 0 0);
  --text-secondary: oklch(75% 0 0);
  --text-muted: oklch(55% 0 0);
  --border: oklch(30% 0 0);
  --border-light: oklch(40% 0 0);

  /* Typography */
  --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --fs-hero: clamp(2rem, 5vw, 3.5rem);
  --fs-h2: clamp(1.5rem, 3.5vw, 2.5rem);
  --fs-h3: clamp(1.125rem, 2vw, 1.5rem);
  --fs-body: clamp(0.875rem, 1.5vw, 1.125rem);
  --fs-small: 0.875rem;
  --fs-xs: 0.75rem;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* Reset */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-main);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

input, select {
  font-family: inherit;
  font-size: inherit;
}

/* ===== HEADER ===== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-sm) var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(to bottom, oklch(0% 0.02 0 / 0.8), transparent);
  transition: background var(--transition-base);
}

.site-header.scrolled {
  background: oklch(0% 0.02 0 / 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.header-left {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.logo {
  font-size: 1.75rem;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--accent);
  text-transform: uppercase;
}

.header-right {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.lang-select {
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 0.4rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  cursor: pointer;
}

.btn-signin {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--fs-small);
  transition: background var(--transition-fast);
  display: inline-block;
}

.btn-signin:hover {
  background: var(--accent-hover);
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: -20px;
  background:
    /* Mosaic of tilted poster-like shapes */
    linear-gradient(135deg, oklch(55% 0.26 25 / 0.15) 0%, transparent 30%),
    linear-gradient(225deg, oklch(50% 0.20 280 / 0.12) 0%, transparent 25%),
    linear-gradient(315deg, oklch(45% 0.18 150 / 0.10) 0%, transparent 28%),
    linear-gradient(45deg, oklch(60% 0.22 50 / 0.12) 0%, transparent 32%),
    linear-gradient(160deg, oklch(55% 0.26 25 / 0.10) 10%, transparent 40%),
    linear-gradient(200deg, oklch(40% 0.15 200 / 0.08) 5%, transparent 35%),
    linear-gradient(340deg, oklch(50% 0.20 300 / 0.10) 8%, transparent 30%),
    linear-gradient(110deg, oklch(45% 0.18 80 / 0.08) 12%, transparent 38%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center top, oklch(0% 0 0 / 0.3), oklch(0% 0 0 / 0.85) 60%),
    radial-gradient(ellipse at center bottom, oklch(0% 0 0 / 0.95), oklch(0% 0 0 / 0.5) 70%);
  z-index: 1;
}

.hero-posters {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  opacity: 0.25;
}

.poster-shape {
  width: 120px;
  height: 170px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  transform: rotate(var(--rot, 0deg)) translateY(var(--ty, 0px));
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: var(--space-xl) var(--space-lg);
}

.hero-title {
  font-size: var(--fs-hero);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.hero-subtitle {
  font-size: var(--fs-h3);
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.hero-prompt {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.email-form {
  display: flex;
  gap: var(--space-xs);
  max-width: 520px;
  margin: 0 auto;
}

.email-form input[type="email"] {
  flex: 1;
  padding: 0.875rem 1rem;
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.email-form input[type="email"]::placeholder {
  color: var(--text-muted);
}

.email-form input[type="email"]:focus {
  border-color: var(--text-secondary);
}

.btn-cta {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  white-space: nowrap;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.btn-cta:hover {
  background: var(--accent-hover);
}

.btn-cta .arrow {
  font-size: 1.25em;
  line-height: 1;
}

.hero-divider {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: var(--bg-surface);
  z-index: 3;
}

/* ===== TRENDING ===== */
.trending {
  background: var(--bg-surface);
  padding: var(--space-xl) var(--space-lg);
}

.section-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-lg);
  letter-spacing: -0.01em;
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--space-sm) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.trending-card {
  position: relative;
  flex: 0 0 200px;
  height: 280px;
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.trending-card:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 30px oklch(0% 0 0 / 0.5);
}

.trending-card .poster-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.trending-card .rank {
  position: absolute;
  bottom: -10px;
  left: -5px;
  z-index: 1;
  font-size: 8rem;
  font-weight: 900;
  line-height: 1;
  color: oklch(100% 0 0 / 0.15);
  -webkit-text-stroke: 2px oklch(100% 0 0 / 0.25);
  letter-spacing: -0.04em;
  pointer-events: none;
}

.trending-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-sm);
  background: linear-gradient(to top, oklch(0% 0 0 / 0.9), transparent);
  z-index: 2;
}

.trending-card .card-title {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.2;
}

.trending-card .card-rank-label {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-top: 2px;
}

.carousel-arrow {
  position: absolute;
  right: -8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: oklch(20% 0 0 / 0.9);
  border: 1px solid var(--border);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.carousel-arrow:hover {
  background: oklch(30% 0 0);
  transform: translateY(-50%) scale(1.1);
}

.carousel-arrow:active {
  transform: translateY(-50%) scale(0.95);
}

/* ===== FEATURES ===== */
.features {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-sm);
}

.feature-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 220px;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition-base);
}

.feature-card:hover {
  transform: translateY(-4px);
}

.feature-card .feature-text h3 {
  font-size: var(--fs-h3);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--space-xs);
}

.feature-card .feature-text p {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.5;
}

.feature-card .feature-icon {
  align-self: flex-end;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: var(--space-sm);
}

.feature-card .feature-icon svg {
  width: 40px;
  height: 40px;
  stroke: var(--text-primary);
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ===== FAQ ===== */
.faq {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  margin-bottom: var(--space-xs);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  font-size: var(--fs-body);
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background var(--transition-fast);
  border-radius: var(--radius-sm);
}

.faq-question:hover {
  background: oklch(22% 0.01 0);
}

.faq-question[aria-expanded="true"] {
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.faq-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-question[aria-expanded="true"] .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
  background: var(--bg-card);
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
}

.faq-answer.open {
  max-height: 400px;
}

.faq-answer-inner {
  padding: var(--space-sm) var(--space-md) var(--space-md);
  font-size: var(--fs-body);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== CTA SECTION ===== */
.cta-section {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.cta-section .cta-prompt {
  font-size: var(--fs-h3);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--bg-primary);
  padding: var(--space-xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--border);
}

.footer-contact {
  font-size: var(--fs-small);
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.footer-contact a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-contact a:hover {
  color: var(--text-secondary);
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.footer-links a {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  text-decoration: underline;
  padding: 0.25rem 0;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--text-secondary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.footer-bottom .lang-select {
  margin-bottom: var(--space-sm);
}

.footer-legal {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  max-width: 400px;
  line-height: 1.5;
}

.footer-legal a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-legal a:hover {
  color: var(--text-secondary);
}

/* ===== LOGIN PAGE ===== */
.login-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.login-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-xl) var(--space-lg);
}

.login-card {
  width: 100%;
  max-width: 420px;
  padding: var(--space-lg);
}

.login-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-xs);
}

.login-subtext {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.login-subtext a {
  color: var(--text-secondary);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.login-subtext a:hover {
  color: var(--text-primary);
}

.form-group {
  margin-bottom: var(--space-sm);
  position: relative;
}

.form-group label {
  display: block;
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-bottom: 4px;
  font-weight: 500;
}

.form-group input {
  width: 100%;
  padding: 0.875rem 1rem;
  background: oklch(22% 0.01 0);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.form-group input::placeholder {
  color: var(--text-muted);
}

.form-group input:focus {
  border-color: var(--text-secondary);
}

.btn-login {
  width: 100%;
  padding: 0.875rem;
  background: var(--accent);
  color: var(--text-primary);
  border: none;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  margin-top: var(--space-sm);
  transition: background var(--transition-fast);
}

.btn-login:hover {
  background: var(--accent-hover);
}

.help-toggle {
  margin-top: var(--space-md);
  text-align: center;
}

.help-toggle button {
  color: var(--text-muted);
  font-size: var(--fs-small);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.help-toggle button:hover {
  color: var(--text-secondary);
}

.help-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
  margin-top: var(--space-xs);
}

.help-content.open {
  max-height: 300px;
}

.help-content-inner {
  padding: var(--space-sm);
  background: var(--bg-card);
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.6;
}

.help-content-inner a {
  color: var(--text-secondary);
  text-decoration: underline;
}

.help-content-inner a:hover {
  color: var(--text-primary);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .trending-card {
    flex: 0 0 170px;
    height: 240px;
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--space-sm) var(--space-md);
  }
  .hero-content {
    padding: var(--space-lg) var(--space-md);
  }
  .email-form {
    flex-direction: column;
  }
  .btn-cta {
    justify-content: center;
  }
  .features-grid {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }
  .feature-card {
    min-height: auto;
    padding: var(--space-md);
  }
  .trending-card {
    flex: 0 0 150px;
    height: 210px;
  }
  .trending-card .rank {
    font-size: 6rem;
  }
  .footer-links {
    grid-template-columns: repeat(2, 1fr);
  }
  .cta-section,
  .trending,
  .features,
  .faq {
    padding: var(--space-xl) var(--space-md);
  }
}

@media (max-width: 480px) {
  .logo {
    font-size: 1.35rem;
  }
  .trending-card {
    flex: 0 0 130px;
    height: 185px;
  }
  .trending-card .rank {
    font-size: 5rem;
  }
  .trending-card .card-title {
    font-size: 0.8rem;
  }
  .hero-title {
    font-size: clamp(1.75rem, 7vw, 2.5rem);
  }
  .carousel-arrow {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }
}

raw_arguments.content:
/* StreamWave Design System */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  /* Color Palette — OKLCH */
  --bg-primary: oklch(0% 0 0);
  --bg-surface: oklch(14.5% 0.01 0);
  --bg-elevated: oklch(20% 0.01 0);
  --bg-card: oklch(17% 0.01 0);
  --accent: oklch(55% 0.26 25);
  --accent-hover: oklch(58% 0.28 25);
  --accent-dark: oklch(35% 0.20 25);
  --text-primary: oklch(100% 0 0);
  --text-secondary: oklch(75% 0 0);
  --text-muted: oklch(55% 0 0);
  --border: oklch(30% 0 0);
  --border-light: oklch(40% 0 0);

  /* Typography */
  --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --fs-hero: clamp(2rem, 5vw, 3.5rem);
  --fs-h2: clamp(1.5rem, 3.5vw, 2.5rem);
  --fs-h3: clamp(1.125rem, 2vw, 1.5rem);
  --fs-body: clamp(0.875rem, 1.5vw, 1.125rem);
  --fs-small: 0.875rem;
  --fs-xs: 0.75rem;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* Reset */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-main);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  color: inherit;
}

input, select {
  font-family: inherit;
  font-size: inherit;
}

/* ===== HEADER ===== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-sm) var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(to bottom, oklch(0% 0.02 0 / 0.8), transparent);
  transition: background var(--transition-base);
}

.site-header.scrolled {
  background: oklch(0% 0.02 0 / 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.header-left {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.logo {
  font-size: 1.75rem;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--accent);
  text-transform: uppercase;
}

.header-right {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.lang-select {
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 0.4rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  cursor: pointer;
}

.btn-signin {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--fs-small);
  transition: background var(--transition-fast);
  display: inline-block;
}

.btn-signin:hover {
  background: var(--accent-hover);
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.hero-bg::before {
  content: '';
  position: absolute;
  inset: -20px;
  background:
    /* Mosaic of tilted poster-like shapes */
    linear-gradient(135deg, oklch(55% 0.26 25 / 0.15) 0%, transparent 30%),
    linear-gradient(225deg, oklch(50% 0.20 280 / 0.12) 0%, transparent 25%),
    linear-gradient(315deg, oklch(45% 0.18 150 / 0.10) 0%, transparent 28%),
    linear-gradient(45deg, oklch(60% 0.22 50 / 0.12) 0%, transparent 32%),
    linear-gradient(160deg, oklch(55% 0.26 25 / 0.10) 10%, transparent 40%),
    linear-gradient(200deg, oklch(40% 0.15 200 / 0.08) 5%, transparent 35%),
    linear-gradient(340deg, oklch(50% 0.20 300 / 0.10) 8%, transparent 30%),
    linear-gradient(110deg, oklch(45% 0.18 80 / 0.08) 12%, transparent 38%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center top, oklch(0% 0 0 / 0.3), oklch(0% 0 0 / 0.85) 60%),
    radial-gradient(ellipse at center bottom, oklch(0% 0 0 / 0.95), oklch(0% 0 0 / 0.5) 70%);
  z-index: 1;
}

.hero-posters {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  opacity: 0.25;
}

.poster-shape {
  width: 120px;
  height: 170px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  transform: rotate(var(--rot, 0deg)) translateY(var(--ty, 0px));
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: var(--space-xl) var(--space-lg);
}

.hero-title {
  font-size: var(--fs-hero);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.hero-subtitle {
  font-size: var(--fs-h3);
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.hero-prompt {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.email-form {
  display: flex;
  gap: var(--space-xs);
  max-width: 520px;
  margin: 0 auto;
}

.email-form input[type="email"] {
  flex: 1;
  padding: 0.875rem 1rem;
  background: oklch(20% 0 0 / 0.6);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.email-form input[type="email"]::placeholder {
  color: var(--text-muted);
}

.email-form input[type="email"]:focus {
  border-color: var(--text-secondary);
}

.btn-cta {
  background: var(--accent);
  color: var(--text-primary);
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  white-space: nowrap;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.btn-cta:hover {
  background: var(--accent-hover);
}

.btn-cta .arrow {
  font-size: 1.25em;
  line-height: 1;
}

.hero-divider {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: var(--bg-surface);
  z-index: 3;
}

/* ===== TRENDING ===== */
.trending {
  background: var(--bg-surface);
  padding: var(--space-xl) var(--space-lg);
}

.section-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-lg);
  letter-spacing: -0.01em;
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--space-sm) 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.trending-card {
  position: relative;
  flex: 0 0 200px;
  height: 280px;
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.trending-card:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 30px oklch(0% 0 0 / 0.5);
}

.trending-card .poster-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.trending-card .rank {
  position: absolute;
  bottom: -10px;
  left: -5px;
  z-index: 1;
  font-size: 8rem;
  font-weight: 900;
  line-height: 1;
  color: oklch(100% 0 0 / 0.15);
  -webkit-text-stroke: 2px oklch(100% 0 0 / 0.25);
  letter-spacing: -0.04em;
  pointer-events: none;
}

.trending-card .card-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-sm);
  background: linear-gradient(to top, oklch(0% 0 0 / 0.9), transparent);
  z-index: 2;
}

.trending-card .card-title {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.2;
}

.trending-card .card-rank-label {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-top: 2px;
}

.carousel-arrow {
  position: absolute;
  right: -8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: oklch(20% 0 0 / 0.9);
  border: 1px solid var(--border);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.carousel-arrow:hover {
  background: oklch(30% 0 0);
  transform: translateY(-50%) scale(1.1);
}

.carousel-arrow:active {
  transform: translateY(-50%) scale(0.95);
}

/* ===== FEATURES ===== */
.features {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-sm);
}

.feature-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 220px;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition-base);
}

.feature-card:hover {
  transform: translateY(-4px);
}

.feature-card .feature-text h3 {
  font-size: var(--fs-h3);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: var(--space-xs);
}

.feature-card .feature-text p {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.5;
}

.feature-card .feature-icon {
  align-self: flex-end;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: var(--space-sm);
}

.feature-card .feature-icon svg {
  width: 40px;
  height: 40px;
  stroke: var(--text-primary);
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ===== FAQ ===== */
.faq {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  margin-bottom: var(--space-xs);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  font-size: var(--fs-body);
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: background var(--transition-fast);
  border-radius: var(--radius-sm);
}

.faq-question:hover {
  background: oklch(22% 0.01 0);
}

.faq-question[aria-expanded="true"] {
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.faq-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq-question[aria-expanded="true"] .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
  background: var(--bg-card);
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
}

.faq-answer.open {
  max-height: 400px;
}

.faq-answer-inner {
  padding: var(--space-sm) var(--space-md) var(--space-md);
  font-size: var(--fs-body);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ===== CTA SECTION ===== */
.cta-section {
  background: var(--bg-primary);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.cta-section .cta-prompt {
  font-size: var(--fs-h3);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--bg-primary);
  padding: var(--space-xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--border);
}

.footer-contact {
  font-size: var(--fs-small);
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.footer-contact a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-contact a:hover {
  color: var(--text-secondary);
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.footer-links a {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  text-decoration: underline;
  padding: 0.25rem 0;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--text-secondary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.footer-bottom .lang-select {
  margin-bottom: var(--space-sm);
}

.footer-legal {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  max-width: 400px;
  line-height: 1.5;
}

.footer-legal a {
  text-decoration: underline;
  color: var(--text-muted);
}

.footer-legal a:hover {
  color: var(--text-secondary);
}

/* ===== LOGIN PAGE ===== */
.login-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.login-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-xl) var(--space-lg);
}

.login-card {
  width: 100%;
  max-width: 420px;
  padding: var(--space-lg);
}

.login-heading {
  font-size: var(--fs-h2);
  font-weight: 800;
  margin-bottom: var(--space-xs);
}

.login-subtext {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  margin-bottom: var(--space-lg);
}

.login-subtext a {
  color: var(--text-secondary);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.login-subtext a:hover {
  color: var(--text-primary);
}

.form-group {
  margin-bottom: var(--space-sm);
  position: relative;
}

.form-group label {
  display: block;
  font-size: var(--fs-xs);
  color: var(--text-muted);
  margin-bottom: 4px;
  font-weight: 500;
}

.form-group input {
  width: 100%;
  padding: 0.875rem 1rem;
  background: oklch(22% 0.01 0);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: var(--fs-body);
  outline: none;
  transition: border-color var(--transition-fast);
}

.form-group input::placeholder {
  color: var(--text-muted);
}

.form-group input:focus {
  border-color: var(--text-secondary);
}

.btn-login {
  width: 100%;
  padding: 0.875rem;
  background: var(--accent);
  color: var(--text-primary);
  border: none;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: var(--fs-body);
  margin-top: var(--space-sm);
  transition: background var(--transition-fast);
}

.btn-login:hover {
  background: var(--accent-hover);
}

.help-toggle {
  margin-top: var(--space-md);
  text-align: center;
}

.help-toggle button {
  color: var(--text-muted);
  font-size: var(--fs-small);
  text-decoration: underline;
  transition: color var(--transition-fast);
}

.help-toggle button:hover {
  color: var(--text-secondary);
}

.help-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
  margin-top: var(--space-xs);
}

.help-content.open {
  max-height: 300px;
}

.help-content-inner {
  padding: var(--space-sm);
  background: var(--bg-card);
  border-radius: var(--radius-sm);
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.6;
}

.help-content-inner a {
  color: var(--text-secondary);
  text-decoration: underline;
}

.help-content-inner a:hover {
  color: var(--text-primary);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .trending-card {
    flex: 0 0 170px;
    height: 240px;
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--space-sm) var(--space-md);
  }
  .hero-content {
    padding: var(--space-lg) var(--space-md);
  }
  .email-form {
    flex-direction: column;
  }
  .btn-cta {
    justify-content: center;
  }
  .features-grid {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }
  .feature-card {
    min-height: auto;
    padding: var(--space-md);
  }
