  .trending-card {
    flex: 0 0 130px;
    height: 185px;
  }
  .trending-card .rank {
    font-size: 5rem;
  }
  .trending-card .card-title {
    font-size: 0.8rem;
  }
  .hero-title {
    font-size: clamp(1.75rem, 7vw, 2.5rem);
  }
  .carousel-arrow {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }
}

